import {roofPlane,projectedRoofAnchor,anchoredRoofDetail,roofDetailPolygonsOnFace,roofWorldPoint} from './building-roof-details.js?v=scripted-ending-ranks-1';
import {detailPaletteHTML,mountBuildingDetailPalette} from './building-detail-palette.js?v=scripted-ending-ranks-1';
import {DECAL_NAMES,MAX_BUILDING_DECALS,anchoredDecal,projectedWallAnchor,validateBuildingDecals,wallWorldPoint,decalPolygonsOnFace} from './building-decals.js?v=scripted-ending-ranks-1';
import {projectedBuildingSurfaces,pickBuildingSurface,pointInBuildingSurface} from './building-surface-picking.js?v=scripted-ending-ranks-1';
import {buildingPropPickFaces,pickBuildingProp} from './building-prop-picking.js?v=scripted-ending-ranks-1';
import {projectBuildingPoint} from './building-footprints.js?v=scripted-ending-ranks-1';
export const anchoredDetailMode=mode=>['anchored-detail','sample-decal','erase-decal'].includes(mode);
export function mountBuildingDecalEditor(root,canvas,{get,camera,mode,material,apply,applyRoof,render,status}){
 root.innerHTML=`<fieldset id="anchoredDetailControls"><legend>Anchored details</legend><label>Surface<select id="decalSurface"><option value="wall">Wall</option><option value="roof">Roof</option></select></label>${detailPaletteHTML()}<div class="block-editor-controls"><label>Width (tiles)<input id="decalWidth" type="number" min=".25" max="10" step=".25" value="2"></label><label><span id="decalSizeLabel">Height (floors)</span><input id="decalHeight" type="number" min=".25" max="25" step=".25" value="2"></label></div><label><input id="decalSnap" type="checkbox"> Snap anchor to surface tile</label><p class="fine">The cross marks the lower-left corner at the cursor. Enable snapping to align with surface tiles. Details extend right and up, clipping at surface edges, gaps and slopes. On roofs, choose Skylight or Vent grille. Click and release to place; Shift or Escape cancels. Select an anchored detail to reuse its design and size. Drag Erase across details and release to remove them together; Undo restores the whole stroke.</p></fieldset>`;
 const $=id=>root.querySelector('#'+id),surface=$('decalSurface'),kind=$('decalKind'),width=$('decalWidth'),height=$('decalHeight'),snap=$('decalSnap'),controls=$('anchoredDetailControls');
 const palette=mountBuildingDetailPalette(root,{get,kind,surface:()=>surface.value||'wall'});
 const base=Object.fromEntries(['onpointerdown','onpointermove','onpointerup','onpointercancel','onkeydown','onwheel'].map(k=>[k,canvas[k]]));let hover=null,pending=null,cache=null;
 const roof=()=>surface.value==='roof',active=()=>anchoredDetailMode(mode.value),point=e=>{const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height};};
 function geometry(){const d=get(),key=[d.blocks,d.voxels,d.blockGeometry,d.footprint,d.props,d.rotation];if(!cache||key.some((v,i)=>v!==cache.key[i]))cache={key,faces:projectedBuildingSurfaces(d,d.rotation),props:buildingPropPickFaces(d,d.rotation)};return cache;}
 function pick(p){if(!p)return null;const f=geometry();if(pickBuildingProp(f.props,p,camera())!==null)return null;const face=pickBuildingSurface(f.faces,p,camera());return face&&(roof()?face.side===4&&roofPlane(face):face.side!==4)?face:null;}
 function owner(face,p){if(!face)return null;const d=get(),c=camera(),local={x:(p.x-c.x)/c.zoom,y:(p.y-c.y)/c.zoom},polygons=roof()?roofDetailPolygonsOnFace(face,d.roofDetails,d):decalPolygonsOnFace(face,d.decals,d);for(let i=polygons.length-1;i>=0;i--)if(pointInBuildingSurface(local,polygons[i].points.map(p=>projectBuildingPoint(p,d.rotation,d.footprint))))return polygons[i].owner;return null;}
 const signature=()=>JSON.stringify([get().blocks,get().voxels,get().blockGeometry,get().decals,get().roofDetails,get().props,get().footprint,get().rotation,camera()]);
 function placement(face){if(!face)return null;try{if(roof()){const c=camera(),anchor=snap.checked||!hover?undefined:projectedRoofAnchor(face,{x:(hover.x-c.x)/c.zoom,y:(hover.y-c.y)/c.zoom},get());return anchoredRoofDetail(face,Number(kind.value),Number(width.value),Number(height.value),anchor);}const d=anchoredDecal(face,Number(kind.value),Number(width.value),Math.round(Number(height.value)*140)/1000);if(snap.checked||!hover)return d;const c=camera(),anchor=projectedWallAnchor(face,{x:(hover.x-c.x)/c.zoom,y:(hover.y-c.y)/c.zoom},get());return validateBuildingDecals([{...d,...anchor}])[0];}catch(error){status.textContent=error.message;return null;}}
 function describe(face){if(!face){status.textContent=roof()?'Point at a visible roof. Choose Skylight or Vent grille.':'Point at a visible wall on a block or layered building.';return;}status.textContent=mode.value==='anchored-detail'?`Lower-left anchor ${snap.checked?'snapped to wall tile':'at cursor'} · width ${width.value} tiles · ${roof()?'depth':'height'} ${height.value} ${roof()?'tiles':'floors'}.`:'Point at the visible part of an anchored detail to select or erase it.';}
 function sample(face){const index=owner(face,hover),d=index===null?null:(roof()?get().roofDetails:get().decals)[index];if(!d){status.textContent='No anchored detail here. Your selection is unchanged.';return;}kind.value=String(d.kind);width.value=String(d.width);height.value=String(roof()?d.depth:Math.round(d.height/.14*1000)/1000);palette.refresh();status.textContent=`Selected ${roof()&&d.kind===1?'Skylight':DECAL_NAMES[d.kind]}. The building is unchanged.`;}
 function commit(action){const list=(roof()?get().roofDetails:get().decals)||[],write=roof()?applyRoof:apply;if(action.kind==='place'){if((get().decals?.length||0)+(get().roofDetails?.length||0)>=MAX_BUILDING_DECALS){status.textContent='Remove an anchored detail before adding another (32 maximum).';return;}write([...list,action.detail]);}else{const indices=action.indices??new Set(action.index===null?[]:[action.index]);if(indices.size)write(list.filter((_,i)=>!indices.has(i)));}}
 function action(face){return mode.value==='anchored-detail'?{kind:'place',detail:placement(face)}:{kind:'erase',index:owner(face,hover)};}
 function extendErase(next){
  if(pending?.kind!=='erase')return;
  if(pending.signature!==signature()){pending=null;return;}
  const start=pending.last,steps=Math.min(256,Math.max(1,Math.ceil(Math.hypot(next.x-start.x,next.y-start.y)/2)));
  for(let i=1;i<=steps;i++){const p={x:start.x+(next.x-start.x)*i/steps,y:start.y+(next.y-start.y)*i/steps};if(p.x<0||p.x>canvas.width||p.y<0||p.y>canvas.height)continue;const index=owner(pick(p),p);if(index!==null)pending.indices.add(index);}
  pending.last=next;status.textContent=`${pending.indices.size} detail${pending.indices.size===1?'':'s'} selected for erasure. Release to erase; Shift or Escape cancels.`;
 }
 const previousMode=mode.onchange;mode.onchange=()=>{pending=null;hover=null;previousMode?.();refresh();if(active()){material.disabled=true;describe(null);render();}};
 surface.onchange=()=>{pending=null;hover=null;refresh();describe(null);render();};
 for(const control of [kind,width,height,snap])control.onchange=control.oninput=()=>{pending=null;render();};
 function refresh(){$('decalSizeLabel').textContent=roof()?'Depth (tiles)':'Height (floors)';height.max=roof()?'10':'25';controls.hidden=!active();for(const c of [kind,width,height,snap])c.disabled=mode.value!=='anchored-detail';palette.refresh();}
 canvas.onpointerdown=e=>{if(pending)return;if(!active())return base.onpointerdown?.(e);if(e.button!==0)return;e.preventDefault();canvas.focus({preventScroll:true});hover=point(e);const face=pick(hover);if(mode.value==='sample-decal')sample(face);else{const next=action(face);pending=next.kind==='place'&&!next.detail?null:{id:e.pointerId,signature:signature(),...next,...(next.kind==='erase'?{indices:new Set(next.index===null?[]:[next.index]),last:hover}:{})};if(pending)canvas.setPointerCapture(e.pointerId);}render();};
 canvas.onpointermove=e=>{if(!active())return base.onpointermove?.(e);if(pending&&pending.id!==e.pointerId)return;hover=point(e);if(pending?.kind==='erase')extendErase(hover);else describe(pick(hover));render();};
 canvas.onpointerup=e=>{if(!active())return base.onpointerup?.(e);if(pending?.id!==e.pointerId)return;if(pending.kind==='erase')extendErase(point(e));if(!pending){render();return;}const action=pending;pending=null;if(!e.shiftKey&&action.signature===signature())commit(action);render();};
 canvas.onpointercancel=e=>{if(!active())return base.onpointercancel?.(e);if(pending&&pending.id!==e.pointerId)return;pending=null;render();};canvas.onwheel=e=>{pending=null;base.onwheel?.(e);};
 canvas.onkeydown=e=>{if(!active())return base.onkeydown?.(e);if(e.key==='Escape'){pending=null;e.preventDefault();e.stopPropagation();render();return;}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter'].includes(e.key)){e.preventDefault();e.stopPropagation();pending=null;hover??={x:128,y:320};const step=e.shiftKey?24:8;if(e.key==='ArrowLeft')hover.x-=step;if(e.key==='ArrowRight')hover.x+=step;if(e.key==='ArrowUp')hover.y-=step;if(e.key==='ArrowDown')hover.y+=step;const face=pick(hover);if(e.key==='Enter'){if(mode.value==='sample-decal')sample(face);else{const next=action(face);if(next.kind!=='place'||next.detail)commit(next);}}else describe(face);render();return;}pending=null;base.onkeydown?.(e);};
 refresh();return{refresh,reset(){pending=null;hover=null;cache=null;refresh();},draw(ctx){if(!active())return;const face=pick(hover);if(!face)return;ctx.save();ctx.strokeStyle='#ffe180';ctx.lineWidth=1.2/camera().zoom;ctx.beginPath();face.polygon.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.stroke();
 if(mode.value==='anchored-detail'){
  const detail=pending?.detail??placement(face);
  if(detail){
   const project=p=>projectBuildingPoint(p,get().rotation,get().footprint);
   const [x,y]=project(roof()?roofWorldPoint(detail.plane,[detail.u,detail.v]):wallWorldPoint(detail.side,detail.plane,[detail.u,detail.z])),r=4/camera().zoom;ctx.beginPath();ctx.moveTo(x-r,y);ctx.lineTo(x+r,y);ctx.moveTo(x,y-r);ctx.lineTo(x,y+r);ctx.stroke();
  }
 }
 ctx.restore();}};
}
